#!/usr/bin/env node
"use strict";
/* helper/*.tcl are the source of truth; the page needs copies too, for the
   "no helper running" zip bundle (it is opened from file:// and cannot read them).
   Regenerates js/23-vivado-tcl.js — run `npm run sync-tcl` after editing a .tcl.
   tests/board-helper.spec.js fails if the two drift apart. */
const fs = require("fs");
const path = require("path");

function render() {
	const read = f => fs.readFileSync(path.join(__dirname, f), "utf8");
	return `"use strict";

/* GENERATED by helper/sync-tcl.js from helper/build.tcl and helper/program.tcl —
   do not edit here; edit the .tcl and run \`npm run sync-tcl\`. */
const VIVADO_TCL = ${JSON.stringify({ build: read("build.tcl"), program: read("program.tcl") }, null, "\t")};
`;
}
const OUT = path.join(__dirname, "..", "js", "23-vivado-tcl.js");
if (require.main === module) {
	fs.writeFileSync(OUT, render());
	console.log("wrote " + path.relative(process.cwd(), OUT));
}
module.exports = { render, OUT };
